    private val ICON_MAP: Map<String, IconMeta> = ALL_ICONS.associateBy { it.key }
    private val RAW_MAP: Map<String, IconMeta> = ALL_ICONS.associateBy { it.rawName }
    private val VECTOR_CACHE = HashMap<String, ImageVector?>()

    fun isRemixIcon(key: String?): Boolean {
        if (key.isNullOrBlank()) return false
        val clean = key.trim()
        return clean.startsWith(PREFIX) || RAW_MAP.containsKey(clean)
    }

    fun findMeta(key: String?): IconMeta? {
        if (key.isNullOrBlank()) return null
        val clean = key.trim()
        return ICON_MAP[clean] ?: RAW_MAP[clean] ?: if (clean.startsWith(PREFIX)) {
            RAW_MAP[clean.substring(PREFIX.length)]
        } else {
            ICON_MAP["$PREFIX$clean"]
        }
    }

    /**
     * 将 PathData 转换为 Compose 的 ImageVector，支持带内存缓存
     */
    fun find(key: String?): ImageVector? {
        val meta = findMeta(key) ?: return null
        synchronized(VECTOR_CACHE) {
            val cached = VECTOR_CACHE[meta.key]
            if (cached != null) return cached
        }

        val vector = try {
            val pathNodes = PathParser().parsePathString(meta.pathData).toNodes()
            ImageVector.Builder(
                name = meta.rawName,
                defaultWidth = 24.dp,
                defaultHeight = 24.dp,
                viewportWidth = 24f,
                viewportHeight = 24f,
            ).addPath(
                pathData = pathNodes,
                fill = SolidColor(Color.White),
            ).build()
        } catch (_: Throwable) {
            null
        }

        synchronized(VECTOR_CACHE) {
            VECTOR_CACHE[meta.key] = vector
        }
        return vector
    }
}
